# A very simple character-level tokenizer
class SimpleTokenizer:
    def __init__(self, text):
        chars = sorted(set(text))
        self.vocab = {c: i for i, c in enumerate(chars)}
        self.inv_vocab = {i: c for c, i in self.vocab.items()}

    def encode(self, text):
        return [self.vocab[c] for c in text]

    def decode(self, ids):
        return ''.join(self.inv_vocab[i] for i in ids)

tok = SimpleTokenizer("hello world")
print("vocab size:", len(tok.vocab))

ids = tok.encode("hello")
print("hello →", ids)
print("decoded:", tok.decode(ids))

